#include "darc.h"
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <stdio.h>
#include <errno.h>

typedef struct { char *text; size_t indent,line; } YLine;
typedef struct { YLine *v; size_t n,cap,pos; char *err; size_t errn,errline,errcol; } YP;
static DarcValue*ynew(DarcValType t){DarcValue*v=darc_calloc(1,sizeof*v);if(v)v->t=t;return v;}
static void ye(YP*y,size_t line,size_t col,const char*m){y->errline=line;y->errcol=col;if(y->err&&y->errn)snprintf(y->err,y->errn,"%s",m);}
static int yaadd(DarcValue*a,DarcValue*x){if(a->u.arr.n==a->u.arr.cap){size_t nc=a->u.arr.cap?a->u.arr.cap*2:8;DarcValue**p=darc_realloc(a->u.arr.v,nc*sizeof*p);if(!p)return -1;a->u.arr.v=p;a->u.arr.cap=nc;}a->u.arr.v[a->u.arr.n++]=x;return 0;}
static int yoadd(DarcValue*o,char*k,DarcValue*x){for(size_t i=0;i<o->u.obj.n;i++)if(!strcmp(o->u.obj.v[i].key,k))return 1;if(o->u.obj.n==o->u.obj.cap){size_t nc=o->u.obj.cap?o->u.obj.cap*2:8;DarcPair*p=darc_realloc(o->u.obj.v,nc*sizeof*p);if(!p)return -1;o->u.obj.v=p;o->u.obj.cap=nc;}o->u.obj.v[o->u.obj.n++]=(DarcPair){k,x};return 0;}
static char *trimdup(const char*s,size_t n){while(n&&isspace((unsigned char)*s)){s++;n--;}while(n&&isspace((unsigned char)s[n-1]))n--;return darc_strndup(s,n);}
static char *strip_comment(const char*s){DarcBuf b;darc_buf_init(&b);int sq=0,dq=0,esc=0;for(size_t i=0;s[i];i++){char c=s[i];if(esc){esc=0;darc_buf_u8(&b,(uint8_t)c);continue;}if(dq&&c=='\\'){esc=1;darc_buf_u8(&b,(uint8_t)c);continue;}if(!dq&&c=='\'')sq=!sq;else if(!sq&&c=='"')dq=!dq;if(c=='#'&&!sq&&!dq)break;darc_buf_u8(&b,(uint8_t)c);}while(b.len&&isspace(b.data[b.len-1]))b.len--;darc_buf_u8(&b,0);return (char*)b.data;}
static DarcValue *yscalar(YP*y,const char*s,size_t line){while(isspace((unsigned char)*s))s++;size_t n=strlen(s);while(n&&isspace((unsigned char)s[n-1]))n--;if(!n){ye(y,line,1,"empty scalar");return NULL;}if(n==2&&!memcmp(s,"[]",2))return ynew(V_ARR);if(n==2&&!memcmp(s,"{}",2))return ynew(V_OBJ);if((s[0]=='['||s[0]=='{')){ye(y,line,1,"non-empty flow collections unsupported");return NULL;}if(s[0]=='"'){size_t ln=n;DarcValue*v=darc_json_parse((const uint8_t*)s,ln,y->err,y->errn,&y->errline,&y->errcol);if(!v||v->t!=V_STR){if(v)darc_value_free(v);return NULL;}return v;}if(s[0]=='\''){if(n<2||s[n-1]!='\''){ye(y,line,1,"unterminated single-quoted string");return NULL;}DarcBuf b;darc_buf_init(&b);for(size_t i=1;i+1<n;i++){if(s[i]=='\''&&i+1<n-1&&s[i+1]=='\''){darc_buf_u8(&b,'\'');i++;}else darc_buf_u8(&b,(uint8_t)s[i]);}darc_buf_u8(&b,0);DarcValue*v=ynew(V_STR);if(!v){darc_buf_free(&b);return NULL;}v->u.str.s=(char*)b.data;v->u.str.len=b.len-1;return v;}if(s[0]=='&'||s[0]=='*'||s[0]=='!'||s[0]=='%'||!strncmp(s,"---",3)||!strncmp(s,"...",3)){ye(y,line,1,"unsupported YAML feature");return NULL;}char*t=trimdup(s,n);if(!t)return NULL;if(!strcmp(t,"true")||!strcmp(t,"false")){DarcValue*v=ynew(V_BOOL);if(v)v->u.b=t[0]=='t';free(t);return v;}if(!strcmp(t,"null")||!strcmp(t,"~")){free(t);return ynew(V_NULL);}if((t[0]=='-'?isdigit((unsigned char)t[1]):isdigit((unsigned char)t[0]))){char*e=NULL;errno=0;long long z=strtoll(t,&e,10);if(!errno&&e&&!*e){DarcValue*v=ynew(V_INT);if(v)v->u.i=(int64_t)z;free(t);return v;}errno=0;double d=strtod(t,&e);if(!errno&&e&&!*e){DarcValue*v=ynew(V_NUM);if(v)v->u.num=d;free(t);return v;}if(errno==ERANGE){ye(y,line,1,"number overflow");free(t);return NULL;}}
DarcValue*v=ynew(V_STR);if(v){v->u.str.s=t;v->u.str.len=strlen(t);}else free(t);return v;}
static DarcValue *yblock(YP*y,size_t indent,int depth);
static int split_key(const char*s,char**key,const char**rest){int sq=0,dq=0,esc=0;for(size_t i=0;s[i];i++){char c=s[i];if(esc){esc=0;continue;}if(dq&&c=='\\'){esc=1;continue;}if(!dq&&c=='\'')sq=!sq;else if(!sq&&c=='"')dq=!dq;else if(!sq&&!dq&&c==':'){*key=trimdup(s,i);*rest=s+i+1;return *key&&**key?0:-1;}}return -1;}
static DarcValue *yobj(YP*y,size_t indent,int depth){DarcValue*o=ynew(V_OBJ);if(!o)return NULL;while(y->pos<y->n&&y->v[y->pos].indent==indent&&strncmp(y->v[y->pos].text,"-",1)){YLine*l=&y->v[y->pos];char*k=NULL;const char*r=NULL;if(split_key(l->text,&k,&r)){ye(y,l->line,indent+1,"expected mapping key: value");goto bad;}if(strchr(k,'[')||strchr(k,']')||strchr(k,'{')||strchr(k,'}')){ye(y,l->line,indent+1,"complex/flow key unsupported");free(k);goto bad;}y->pos++;while(isspace((unsigned char)*r))r++;DarcValue*v;if(*r){v=yscalar(y,r,l->line);if(!v){free(k);goto bad;}}else{if(y->pos>=y->n||y->v[y->pos].indent<=indent){v=ynew(V_NULL);}else{size_t ni=y->v[y->pos].indent;if(ni<=indent){free(k);goto bad;}v=yblock(y,ni,depth+1);if(!v){free(k);goto bad;}}}int a=yoadd(o,k,v);if(a){ye(y,l->line,indent+1,a==1?"duplicate mapping key":"out of memory");free(k);darc_value_free(v);goto bad;}}return o;bad:darc_value_free(o);return NULL;}
static DarcValue *yarr(YP*y,size_t indent,int depth){DarcValue*a=ynew(V_ARR);if(!a)return NULL;while(y->pos<y->n&&y->v[y->pos].indent==indent&&y->v[y->pos].text[0]=='-'&&(y->v[y->pos].text[1]==0||isspace((unsigned char)y->v[y->pos].text[1]))){YLine*l=&y->v[y->pos];const char*r=l->text+1;while(isspace((unsigned char)*r))r++;y->pos++;DarcValue*v=NULL;if(!*r){if(y->pos>=y->n||y->v[y->pos].indent<=indent){ye(y,l->line,indent+1,"empty sequence item");goto bad;}v=yblock(y,y->v[y->pos].indent,depth+1);}else{char*k=NULL;const char*rest=NULL;if(split_key(r,&k,&rest)==0){DarcValue*o=ynew(V_OBJ);if(!o){free(k);goto bad;}while(isspace((unsigned char)*rest))rest++;DarcValue*x;if(*rest)x=yscalar(y,rest,l->line);else if(y->pos<y->n&&y->v[y->pos].indent>indent)x=yblock(y,y->v[y->pos].indent,depth+1);else x=ynew(V_NULL);if(!x||yoadd(o,k,x)){free(k);darc_value_free(x);darc_value_free(o);goto bad;}v=o;}else v=yscalar(y,r,l->line);}if(!v||yaadd(a,v)){darc_value_free(v);goto bad;}}return a;bad:darc_value_free(a);return NULL;}
static DarcValue *yblock(YP*y,size_t indent,int depth){if(depth>DARC_MAX_CONFIG_DEPTH){if(y->pos<y->n)ye(y,y->v[y->pos].line,indent+1,"nesting depth exceeded");return NULL;}if(y->pos>=y->n)return ynew(V_OBJ);if(y->v[y->pos].indent!=indent){ye(y,y->v[y->pos].line,y->v[y->pos].indent+1,"invalid indentation jump");return NULL;}if(y->v[y->pos].text[0]=='-')return yarr(y,indent,depth);return yobj(y,indent,depth);}
DarcValue *darc_yaml_parse(const uint8_t*s,size_t n,char*err,size_t errn,size_t*line,size_t*col){if(err&&errn)*err=0;if(!darc_valid_utf8(s,n)){if(err&&errn)snprintf(err,errn,"malformed UTF-8");if(line)*line=1;if(col)*col=1;return NULL;}YP y={0};y.err=err;y.errn=errn;size_t p=0,ln=1;while(p<n){size_t st=p;while(p<n&&s[p]!='\n')p++;size_t le=p;if(p<n)p++;if(le>st&&s[le-1]=='\r')le--;size_t ind=0;while(st+ind<le&&s[st+ind]==' ')ind++;if(st+ind<le&&s[st+ind]=='\t'){ye(&y,ln,ind+1,"tab indentation forbidden");goto fail;}char*raw=darc_strndup((const char*)s+st+ind,le-st-ind);if(!raw)goto fail;char*txt=strip_comment(raw);free(raw);if(!txt)goto fail;char*q=txt;while(*q&&isspace((unsigned char)*q))q++;if(*q){if(y.n==y.cap){size_t nc=y.cap?y.cap*2:32;YLine*nv=darc_realloc(y.v,nc*sizeof*nv);if(!nv){free(txt);goto fail;}y.v=nv;y.cap=nc;}y.v[y.n++]=(YLine){txt,ind,ln};}else free(txt);ln++;}if(!y.n){DarcValue*v=ynew(V_OBJ);free(y.v);if(line)*line=1;if(col)*col=1;return v;}if(y.v[0].indent!=0){ye(&y,y.v[0].line,1,"top-level indentation must be zero");goto fail;}DarcValue*v=yblock(&y,0,0);if(v&&y.pos!=y.n){ye(&y,y.v[y.pos].line,y.v[y.pos].indent+1,"inconsistent indentation");darc_value_free(v);v=NULL;}for(size_t i=0;i<y.n;i++)free(y.v[i].text);free(y.v);if(line)*line=y.errline?y.errline:1;if(col)*col=y.errcol?y.errcol:1;return v;fail:for(size_t i=0;i<y.n;i++)free(y.v[i].text);free(y.v);if(line)*line=y.errline?y.errline:ln;if(col)*col=y.errcol?y.errcol:1;return NULL;}
